"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["35411"],{9242(e){e.exports=JSON.parse('{"id":"V4-088","slug":"binomial-option-pricing-model","term":"Binomial Option Pricing Model","also_known_as":[],"difficulty":"Advanced","definition":"The binomial option pricing model is a method of valuing options by assuming that the underlying asset\u2019s price can move up or down by set amounts in each of a series of time steps, building a tree of possible prices.","explanation":["The model was developed by John Cox, Stephen Ross and Mark Rubinstein in 1979. It breaks the time until expiry into steps. At each step, the price moves either up or down. The option\u2019s value is calculated at the end of the tree and then worked backwards to today, using probabilities that make the calculation consistent with a risk-free return.","For a simple one-step example, a share trades at 100 and will be either 120 or 80 next period, with interest rates of zero. A call option with an exercise price of 100 would be worth 20 if the share rises and nothing if it falls. The model\u2019s risk-neutral probability of a rise is 50%, so the option is worth 50% of 20, or 10, today.","With many small steps, the binomial model\u2019s results approach those of the Black-Scholes model.","Its main advantage is flexibility. It can value American options, which can be exercised early, and options with more complex features, which the basic Black-Scholes formula cannot handle."],"note":"","total":1725,"prev":{"slug":"binomial-distribution","term":"Binomial Distribution"},"next":{"slug":"biometric-authentication","term":"Biometric Authentication"}}')}}]);